{
  "AWSTemplateFormatVersion": "2010-09-09",
  "Resources": {
    "TempSAPAccessRole": {
      "Type": "AWS::IAM::Role",
      "Properties": {
        "AssumeRolePolicyDocument": {
          "Version": "2012-10-17",
          "Statement": [{
            "Effect": "Allow",
